-- Client updated website con2026.ods, visible rows 3-9, approved 30 Oct 2026.

-- Latest-sheet decision: Shorts 1850; Wine/Grey Cotton 499 / 599.

-- Keep product/variation identities and historical orders. Only unsupported size stock is disabled.

-- Newly introduced Cotton sizes start at the previously authorized stock of 100.

-- Existing stock and all unrelated prices, products, users and orders are preserved.

SET @dx_cotton_id = (SELECT id FROM tbl_categories WHERE url_slug = 'cotton' LIMIT 1);

SET @dx_cotton_code = (SELECT product_code FROM tbl_products WHERE id = 30);

UPDATE tbl_products SET cat_id = @dx_cotton_id, product_code = @dx_cotton_code, title = 'Cotton Period Panty - Black', url_slug = 'cotton-period-panty-black', price = 499.00, special_price = 0.00, discount = 0, absorbency_volume = 'Up to 40 ml', short_description = '<p>DEXTE COTTON PERIOD PANTY<br>Your everyday cotton comfort. With extra protection built in.</p><p>Periods shouldn&#8217;t put your day on pause. Meet Dexte Cotton Period Panty&#8212;soft cotton comfort with an absorbent core for periods, spotting and mild urinary leaks. From school days to office hours and relaxed evenings, feel more prepared wherever your day takes you.</p><h4>WHY YOU&#8217;LL LOVE IT</h4><p><strong>Soft, breathable comfort:</strong> A 100% cotton body fabric for a comfortable feel against your skin.</p><p><strong>Built-in absorbency:</strong> An absorbent core with a stated capacity of up to 40 ml.</p><p><strong>Flexible period protection:</strong> Wear on its own when suitable for your flow, or pair with a pad for extra backup on heavy-flow days.</p><p><strong>Reassurance beyond periods:</strong> Useful for unexpected spotting and occasional mild urinary leakage.</p><p><strong>Wash, reuse, repeat:</strong> A reusable option that can help reduce disposable pad use when worn on its own.</p><p><strong>Comfort in more sizes:</strong> Available from XS to 6XL, for teenagers and adults&#8212;choose by body measurements.</p><h4>ONE PANTY. DIFFERENT WAYS TO WEAR IT.</h4><p><strong>On light to moderate period days:</strong> Wear without a pad for approximately 4&#8211;6 hours, depending on your flow and how quickly the absorbent layers fill.</p><p><strong>On heavy-flow days:</strong> Pair with a pad for an extra layer of protection against overflow. Change the pad regularly and change the panty if damp or saturated.</p><p><strong>Before and after your period:</strong> Stay prepared for an unexpected start or lingering spotting.</p><p><strong>For mild urinary leakage:</strong> Added reassurance for occasional small leaks during daily activities.<br>COLOUR: Black<br>BODY FABRIC: 100% cotton, with additional absorbent and protective layers<br>ABSORBENCY: Up to 40 ml*</p><table><thead><tr><th>Size</th><th>Price</th></tr></thead><tbody><tr><td>XS&ndash;XL</td><td>&#8377;499</td></tr><tr><td>2XL&ndash;6XL</td><td>&#8377;599</td></tr></tbody></table><p>Your flow. Your fit. Your Dexte comfort.</p><p>Absorbency and wear time vary with flow and use. Change sooner whenever damp, saturated or uncomfortable. Absorbency capacity does not guarantee leak-free wear for a fixed number of hours.</p>', description = '', meta_title = 'Cotton Period Panty - Black | DEXTE', meta_description = 'Shop DEXTE cotton period panties in Black. Sizes XS to 6XL; Rs. 499 up to XL and Rs. 599 for 2XL to 6XL.' WHERE id = 30;

