UPDATE tbl_products SET short_description = REPLACE(REPLACE(short_description, 'is a mid waist style.', 'is made for everyday comfort.'), 'in grey, cream and black', 'in cream and black') WHERE id IN (38,39);

UPDATE tbl_products SET short_description = REPLACE(short_description, 'Mid waist style with a leak-proof layered gusset', 'Soft cotton with a leak-proof layered gusset') WHERE id = 32;

UPDATE tbl_products SET short_description = REPLACE(short_description, '<strong>Colours:</strong> Red and Wine', '<strong>Colours:</strong> Red') WHERE id IN (35,40);

UPDATE tbl_products SET color = '#c96895' WHERE id = 34;

UPDATE tbl_product_variation SET price = NULL WHERE product_id IN (6,7);

UPDATE tbl_product_variation SET price = NULL WHERE product_id IN (30,31,36,37) AND UPPER(size) IN ('XS','S','M','L','XL');

UPDATE tbl_product_variation SET price = 599.00 WHERE product_id IN (30,31,36,37) AND UPPER(size) IN ('XXL','2XL','XXXL','3XL','XXXXL','4XL','XXXXXL','5XL','XXXXXXL','6XL');

INSERT INTO tbl_product_variation (product_id,size,sku,qty,price) SELECT p.id, s.size, CONCAT('COTTON-',p.id,'-',s.size), 100, 599.00 FROM tbl_products p JOIN (SELECT 'XXL' AS size, '2XL' AS alias UNION ALL SELECT 'XXXL','3XL' UNION ALL SELECT 'XXXXL','4XL' UNION ALL SELECT 'XXXXXL','5XL' UNION ALL SELECT 'XXXXXXL','6XL') s LEFT JOIN tbl_product_variation v ON v.product_id = p.id AND UPPER(v.size) IN (s.size,s.alias) WHERE p.id IN (30,31,36,37) AND v.id IS NULL;

UPDATE tbl_product_variation SET qty = 0 WHERE product_id IN (31,36,37) AND UPPER(size) = 'XS';

UPDATE tbl_product_variation SET qty = 0 WHERE product_id IN (6,7) AND UPPER(size) NOT IN ('XS','S','M','L','XL','XXL','2XL');

UPDATE tbl_product_variation SET qty = 0 WHERE product_id IN (1,9,10,11,14,15,16,17,18,19,20,21) AND UPPER(size) NOT IN ('XS','S','M','L','XL','XXL','2XL','XXXL','3XL');

INSERT INTO tbl_product_images (product_id,image,thumb_image,img_tag,position) SELECT p.id,'dx-sheet-cotton-black-logo-v1.jpg','dx-sheet-cotton-black-logo-v1.jpg','Black cotton period panty gold DEXTE logo detail',6 FROM tbl_products p LEFT JOIN tbl_product_images i ON i.product_id = p.id AND i.image = 'dx-sheet-cotton-black-logo-v1.jpg' WHERE p.id = 30 AND i.id IS NULL;

